// Creates src/esthi-questions.js with header + Texas TDLR ids 1-50
import { writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const HEADER = `// ─── PASSBOARD ESTHETICS QUESTION BANK ──────────────────────────────────────
// PSI Texas Esthetician Written Exam — 525-question bank
// Topics: Texas TDLR Laws & Regulations (79) | Infection Control & Sanitation (105) |
//         Nail Structure & Analysis (31) | Nail Care (100) |
//         Skin Care (52) | Facial Treatments (79) |
//         Hair Removal (52) | Facial Makeup (27)
// Format: ESM — import { esthiQuestions } from './esthi-questions.js'
// ──────────────────────────────────────────────────────────────────────────────

export const esthiQuestions = [
`

const topic = '"Texas TDLR Laws & Regulations"'
const topic_es = '"Leyes y Regulaciones de Texas TDLR"'
const psi_topic = '"Licensing & Regulation"'
const psi_topic_es = '"Licencias y Regulaciones"'

function fmt(q) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${psi_topic}, psi_topic_es: ${psi_topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

// ─── TEXAS TDLR LAWS & REGULATIONS (ids 1–79) ────────────────────────────────
const questions = [
  { id: 1, question: "Which Texas state agency licenses and regulates estheticians?", question_es: "¿Qué agencia estatal de Texas licencia y regula a los esteticistas?", options: ["Texas Department of Licensing and Regulation (TDLR)", "Texas State Board of Cosmetology", "Texas Department of Health Services", "Texas Medical Board"], options_es: ["Departamento de Licencias y Regulación de Texas (TDLR)", "Junta Estatal de Cosmetología de Texas", "Departamento de Servicios de Salud de Texas", "Junta Médica de Texas"], correct: 0, explanation: "The Texas Department of Licensing and Regulation (TDLR) regulates esthetics in Texas. TDLR absorbed the functions of the former Texas State Board of Cosmetology (TSBCS) when esthetics was transferred under TDLR's authority." },
  { id: 2, question: "Texas esthetics licensing and regulation is primarily governed by:", question_es: "Las licencias y regulaciones de estética en Texas están principalmente regidas por:", options: ["Texas Occupations Code Chapter 1603 (Cosmetology), which includes esthetics as a specialty within the cosmetology framework", "Texas Health and Safety Code Chapter 147", "Texas Administrative Code Title 25", "Texas Occupations Code Chapter 1601 (Barbering)"], options_es: ["Capítulo 1603 del Código de Ocupaciones de Texas (Cosmetología), que incluye la estética como especialidad dentro del marco de cosmetología", "Capítulo 147 del Código de Salud y Seguridad de Texas", "Título 25 del Código Administrativo de Texas", "Capítulo 1601 del Código de Ocupaciones de Texas (Barbería)"], correct: 0, explanation: "Texas Occupations Code Chapter 1603 governs all cosmetology-related licensing in Texas, including esthetician, master esthetician, cosmetologist, manicurist, and instructor licenses. Esthetics is a defined specialty within this chapter." },
  { id: 3, question: "The detailed administrative rules for Texas esthetics — including sanitation, facility, and operational requirements — are found in:", question_es: "Las reglas administrativas detalladas para la estética de Texas — incluyendo saneamiento, instalaciones y requisitos operativos — se encuentran en:", options: ["Texas Administrative Code Title 16, Chapter 83 (Cosmetology)", "Texas Administrative Code Title 25 (Health Services)", "Texas Occupations Code Chapter 1603 only", "Texas Administrative Code Title 37 (Public Safety)"], options_es: ["Código Administrativo de Texas Título 16, Capítulo 83 (Cosmetología)", "Código Administrativo de Texas Título 25 (Servicios de Salud)", "Solo el Capítulo 1603 del Código de Ocupaciones de Texas", "Código Administrativo de Texas Título 37 (Seguridad Pública)"], correct: 0, explanation: "Texas Administrative Code Title 16, Chapter 83 contains the TDLR-adopted rules implementing Texas Occupations Code Chapter 1603 for cosmetology and esthetics. Chapter 83 specifies sanitation standards, facility requirements, instructor qualifications, and operational rules for esthetics establishments." },
  { id: 4, question: "To qualify for a Texas Esthetician license, an applicant must complete a minimum of:", question_es: "Para calificar para una licencia de Esteticista de Texas, un solicitante debe completar un mínimo de:", options: ["750 hours of approved esthetics education at a TDLR-licensed school", "500 hours at any cosmetology school", "1,500 hours equivalent to the cosmetology operator program", "1,000 hours including apprenticeship hours"], options_es: ["750 horas de educación estética aprobada en una escuela con licencia de TDLR", "500 horas en cualquier escuela de cosmetología", "1,500 horas equivalentes al programa de operador de cosmetología", "1,000 horas incluyendo horas de aprendizaje"], correct: 0, explanation: "Texas requires a minimum of 750 hours of esthetics education at a TDLR-licensed school to qualify for the Esthetician license examination. These hours must be in the esthetics curriculum as defined by TDLR and cannot be substituted with barbering or general cosmetology hours." },
  { id: 5, question: "The minimum age to obtain a Texas Esthetician license is:", question_es: "La edad mínima para obtener una licencia de Esteticista de Texas es:", options: ["17 years old", "18 years old", "16 years old", "21 years old"], options_es: ["17 años", "18 años", "16 años", "21 años"], correct: 0, explanation: "Texas requires applicants to be at least 17 years old to obtain an Esthetician license. Students may begin an esthetics program at 16 and complete the required education hours, then apply upon turning 17." },
  { id: 6, question: "After completing the required education hours, a Texas esthetics candidate must pass examinations administered by:", question_es: "Después de completar las horas de educación requeridas, un candidato de estética de Texas debe pasar los exámenes administrados por:", options: ["PSI Exams, under contract with TDLR — candidates must pass both a written (theory) and practical (skills) examination", "The TDLR office directly, via in-house examiners", "The esthetics school where the applicant completed their education", "A national cosmetology board independent of TDLR"], options_es: ["PSI Exams, bajo contrato con TDLR — los candidatos deben pasar tanto un examen escrito (teoría) como un examen práctico (habilidades)", "La oficina de TDLR directamente, a través de examinadores internos", "La escuela de estética donde el solicitante completó su educación", "Una junta nacional de cosmetología independiente de TDLR"], correct: 0, explanation: "PSI Exams administers the Texas esthetics licensing examinations under contract with TDLR. Candidates must pass both the written (theory) examination and the practical (skills) examination before the Esthetician license is issued." },
  { id: 7, question: "A Texas Esthetician license must be renewed:", question_es: "Una licencia de Esteticista de Texas debe renovarse:", options: ["Every two years (biennially), with the expiration date printed on the license", "Every year", "Every five years", "Only when changing employers or salon locations"], options_es: ["Cada dos años (bienalmente), con la fecha de vencimiento impresa en la licencia", "Cada año", "Cada cinco años", "Solo al cambiar de empleador o ubicación del salón"], correct: 0, explanation: "Texas Esthetician licenses are renewed on a biennial (every two years) cycle. The expiration date is printed on the license. Estheticians must complete renewal and pay the fee before the expiration date to avoid lapse." },
  { id: 8, question: "Texas estheticians must complete how many hours of continuing education per renewal period?", question_es: "¿Cuántas horas de educación continua deben completar los esteticistas de Texas por período de renovación?", options: ["4 hours of TDLR-approved continuing education per 2-year renewal period", "10 hours per year", "6 hours per renewal period", "No continuing education is required for estheticians in Texas"], options_es: ["4 horas de educación continua aprobada por TDLR por período de renovación de 2 años", "10 horas por año", "6 horas por período de renovación", "No se requiere educación continua para los esteticistas en Texas"], correct: 0, explanation: "Texas requires estheticians to complete 4 hours of TDLR-approved continuing education per 2-year renewal period. CE topics may include infection control, professional ethics, and relevant technical subjects. Verify current requirements with TDLR as rules may be updated." },
  { id: 9, question: "Which of the following services is within the scope of practice for a Texas licensed esthetician?", question_es: "¿Cuál de los siguientes servicios está dentro del alcance de práctica de un esteticista con licencia de Texas?", options: ["Cleansing, toning, moisturizing, and performing facials; superficial chemical exfoliation; hair removal by waxing, threading, or tweezing; makeup application; and eyelash/eyebrow tinting", "Performing surgical facelifts and injectable Botox treatments", "Prescribing topical medications for acne or rosacea", "Performing ablative laser resurfacing and deep chemical peels"], options_es: ["Limpiar, tonificar, hidratar y realizar faciales; exfoliación química superficial; depilación con cera, hilo o pinzas; aplicación de maquillaje; y tintura de pestañas/cejas", "Realizar cirugías de lifting facial e inyecciones de Botox", "Prescribir medicamentos tópicos para el acné o la rosácea", "Realizar resurfacing láser ablativo y peels químicos profundos"], correct: 0, explanation: "A Texas Esthetician's scope includes: facial treatments (cleanse, tone, mask, moisturize), superficial chemical exfoliation (non-ablative), mechanical exfoliation (microdermabrasion), waxing, threading, tweezing, makeup, and eyebrow/eyelash services. Medical procedures, prescription services, and deep resurfacing are outside scope." },
  { id: 10, question: "A Texas esthetician is PROHIBITED from performing which of the following?", question_es: "A un esteticista de Texas se le PROHÍBE realizar cuál de las siguientes?", options: ["Ablative laser treatments, deep chemical peels beyond the epidermis, injections, or any procedure requiring a medical license — these are medical procedures outside the esthetics scope", "Eyebrow shaping using tweezers", "Applying a superficial enzyme peel to the face", "Performing a basic facial including steam and extractions"], options_es: ["Tratamientos láser ablativos, peels químicos profundos más allá de la epidermis, inyecciones o cualquier procedimiento que requiera una licencia médica — estos son procedimientos médicos fuera del alcance de la estética", "Dar forma a las cejas usando pinzas", "Aplicar un peel de enzimas superficial en el rostro", "Realizar un facial básico que incluye vapor y extracciones"], correct: 0, explanation: "Texas estheticians are prohibited from performing any procedure that constitutes the practice of medicine — including ablative lasers, injectable treatments (Botox, fillers), deep chemical peels penetrating beyond the epidermis, and prescribing products. These require a physician or other medical license." },
  { id: 11, question: "A Texas esthetics establishment (salon) must obtain which license before opening?", question_es: "Un establecimiento de estética de Texas (salón) debe obtener qué licencia antes de abrir?", options: ["A cosmetology establishment license issued by TDLR for the specific physical location", "A business license from the Texas Secretary of State only", "Each esthetician's individual license covers the establishment — no separate license is needed", "An annual health permit from the local city government"], options_es: ["Una licencia de establecimiento de cosmetología emitida por TDLR para la ubicación física específica", "Solo una licencia comercial del Secretario de Estado de Texas", "La licencia individual de cada esteticista cubre el establecimiento — no se necesita una licencia separada", "Un permiso de salud anual del gobierno local de la ciudad"], correct: 0, explanation: "In addition to individual esthetician licenses, the physical esthetics establishment must hold a TDLR cosmetology establishment license. This applies to salons, spas, and any facility where esthetics services are performed commercially. Both the establishment and individual licenses must be current." },
  { id: 12, question: "The Texas esthetics establishment license is issued to:", question_es: "La licencia de establecimiento de estética de Texas se emite a:", options: ["The owner of the establishment (individual or business entity) for the specific physical location where services are provided", "The most senior licensed esthetician working at the establishment", "Each esthetician working at the location, collectively", "The landlord of the building where the establishment is located"], options_es: ["El propietario del establecimiento (individuo o entidad comercial) para la ubicación física específica donde se brindan los servicios", "El esteticista con licencia más senior que trabaja en el establecimiento", "Cada esteticista que trabaja en la ubicación, colectivamente", "El propietario del edificio donde se encuentra el establecimiento"], correct: 0, explanation: "The establishment license is tied to the owner and the specific physical address. If the establishment moves or changes ownership, a new establishment license is required. The establishment license is separate from the individual esthetician licenses required for each practitioner." },
  { id: 13, question: "A Texas esthetician's license and the establishment license must be displayed:", question_es: "La licencia de esteticista de Texas y la licencia del establecimiento deben exhibirse:", options: ["In a conspicuous location within the establishment, clearly visible to clients", "Only in the owner's back office away from client view", "On the esthetician's person at all times", "Only upon request by a TDLR inspector"], options_es: ["En un lugar visible dentro del establecimiento, claramente visible para los clientes", "Solo en la oficina trasera del propietario fuera de la vista del cliente", "En la persona del esteticista en todo momento", "Solo a solicitud de un inspector de TDLR"], correct: 0, explanation: "Texas law requires that all esthetician licenses and the establishment license be displayed in a conspicuous (clearly visible) location within the establishment where clients can see them. This allows clients and inspectors to verify licensing status." },
  { id: 14, question: "A booth renter (independent contractor) working in a Texas esthetics establishment must:", question_es: "Un arrendatario de espacio (contratista independiente) que trabaja en un establecimiento de estética de Texas debe:", options: ["Hold their own valid Texas Esthetician license and comply with all TDLR rules independently — the establishment license does not cover individual booth renters", "Use the establishment owner's license to practice — no separate license is required", "Only have an apprentice permit to operate as a booth renter", "File a separate independent contractor license with TDLR"], options_es: ["Tener su propia licencia válida de Esteticista de Texas y cumplir con todas las reglas de TDLR de forma independiente — la licencia del establecimiento no cubre a los arrendatarios individuales", "Usar la licencia del propietario del establecimiento para practicar — no se requiere una licencia separada", "Solo tener un permiso de aprendiz para operar como arrendatario de espacio", "Presentar una licencia de contratista independiente separada ante TDLR"], correct: 0, explanation: "Every esthetician practicing in Texas — whether an employee or a booth renter — must hold their own valid TDLR Esthetician license. Booth renters are independent contractors who rent space and are responsible for maintaining their own license, sanitation compliance, and client records." },
  { id: 15, question: "TDLR may inspect a Texas esthetics establishment:", question_es: "TDLR puede inspeccionar un establecimiento de estética de Texas:", options: ["At any time during business hours without prior notice to verify compliance with all applicable TDLR rules", "Only after receiving a formal consumer complaint", "Annually on a fixed schedule announced in advance by certified mail", "Only during the first year after the establishment license is issued"], options_es: ["En cualquier momento durante las horas de negocio sin previo aviso para verificar el cumplimiento de todas las reglas de TDLR aplicables", "Solo después de recibir una queja formal del consumidor", "Anualmente en un horario fijo anunciado con anticipación por correo certificado", "Solo durante el primer año después de que se emite la licencia del establecimiento"], correct: 0, explanation: "TDLR inspectors may conduct unannounced inspections of licensed esthetics establishments during business hours to verify compliance with sanitation rules, licensing display requirements, and other regulatory standards. Establishments must maintain compliance at all times." },
  { id: 16, question: "A consumer who believes a Texas esthetician violated the law should:", question_es: "Un consumidor que cree que un esteticista de Texas violó la ley debe:", options: ["File a formal complaint with TDLR — TDLR will investigate and take appropriate action if a violation is confirmed", "Only pursue civil litigation in small claims court", "Report the violation to the Texas Attorney General's office only", "Post a negative review online — no official regulatory process exists"], options_es: ["Presentar una queja formal ante TDLR — TDLR investigará y tomará las medidas apropiadas si se confirma una violación", "Solo seguir litigios civiles en el tribunal de reclamaciones menores", "Reportar la violación solo a la oficina del Fiscal General de Texas", "Publicar una reseña negativa en línea — no existe ningún proceso regulatorio oficial"], correct: 0, explanation: "TDLR provides a formal complaint process for consumers. Written complaints about licensed estheticians or establishments are investigated by TDLR. When violations are substantiated, TDLR can take administrative action including fines, suspension, or revocation of the license." },
  { id: 17, question: "If a TDLR inspector finds an esthetics establishment in violation of sanitation rules, TDLR may:", question_es: "Si un inspector de TDLR encuentra un establecimiento de estética en violación de las reglas de saneamiento, TDLR puede:", options: ["Issue a notice of violation, require corrective action within a specified timeframe, impose administrative fines, and in serious cases involving immediate health risk, temporarily close the establishment", "Only issue a verbal warning with no documentation", "Automatically revoke the establishment license on the first violation", "Allow 6 months to correct all violations before any action is taken"], options_es: ["Emitir un aviso de violación, requerir acción correctiva dentro de un plazo especificado, imponer multas administrativas y, en casos graves que involucren riesgo inmediato para la salud, cerrar temporalmente el establecimiento", "Solo emitir una advertencia verbal sin documentación", "Revocar automáticamente la licencia del establecimiento en la primera violación", "Permitir 6 meses para corregir todas las violaciones antes de que se tome alguna acción"], correct: 0, explanation: "TDLR uses a graduated enforcement approach. Violations generate notices with correction deadlines and may incur fines. Establishments may be temporarily closed for imminent health hazards (e.g., using contaminated implements). The establishment has due process rights including the ability to appeal." },
  { id: 18, question: "A Texas esthetician who practices without a current, valid license is subject to:", question_es: "Un esteticista de Texas que practica sin una licencia válida y vigente está sujeto a:", options: ["TDLR administrative penalties including fines, cease-and-desist orders, and potential prohibition from future licensure", "Only a verbal warning for a first offense with no further consequences", "Criminal prosecution under federal healthcare fraud statutes", "Automatic revocation of any future license applications regardless of qualifications"], options_es: ["Penalidades administrativas de TDLR incluyendo multas, órdenes de cesar y desistir y posible prohibición de futuras licencias", "Solo una advertencia verbal por una primera infracción sin más consecuencias", "Enjuiciamiento penal bajo los estatutos federales de fraude en el cuidado de la salud", "Revocación automática de cualquier solicitud de licencia futura independientemente de las calificaciones"], correct: 0, explanation: "Practicing esthetics without a valid Texas license violates the Occupations Code. TDLR may impose administrative fines, issue cease-and-desist orders, and deny future license applications. Unlicensed practice may also result in state criminal charges under Texas law." },
  { id: 19, question: "Advertising for a Texas esthetics establishment must be:", question_es: "La publicidad de un establecimiento de estética de Texas debe ser:", options: ["Truthful and not contain false or misleading claims about services offered, credentials held, or prices — deceptive advertising is a violation of TDLR rules", "Approved by TDLR before any publication or distribution", "Limited to print media — online advertising is not regulated by TDLR", "Required to include the TDLR establishment license number in all formats"], options_es: ["Veraz y no contener afirmaciones falsas o engañosas sobre los servicios ofrecidos, las credenciales obtenidas o los precios — la publicidad engañosa es una violación de las reglas de TDLR", "Aprobada por TDLR antes de cualquier publicación o distribución", "Limitada a medios impresos — la publicidad en línea no está regulada por TDLR", "Requerida para incluir el número de licencia del establecimiento de TDLR en todos los formatos"], correct: 0, explanation: "All advertising by Texas esthetics establishments and individual estheticians must be truthful and non-deceptive. False claims about credentials (e.g., claiming to be a Master Esthetician without that license), services, or pricing are TDLR violations subject to disciplinary action." },
  { id: 20, question: "Client records in a Texas esthetics establishment must be:", question_es: "Los registros de clientes en un establecimiento de estética de Texas deben ser:", options: ["Kept confidential — client personal and health information cannot be disclosed without client authorization, consistent with Texas privacy law", "Filed with TDLR monthly as part of sanitation compliance reporting", "Made publicly available upon request since they are business records", "Destroyed after each client visit to protect privacy"], options_es: ["Mantenidos confidencialmente — la información personal y de salud del cliente no puede divulgarse sin autorización del cliente, de acuerdo con la ley de privacidad de Texas", "Presentados ante TDLR mensualmente como parte de los informes de cumplimiento de saneamiento", "Disponibles al público a solicitud ya que son registros comerciales", "Destruidos después de cada visita del cliente para proteger la privacidad"], correct: 0, explanation: "Client records (including health history, skin analysis notes, product reactions, and chemical service records) are confidential. Texas privacy expectations prohibit disclosure without client consent. Proper record keeping also protects the esthetician professionally and demonstrates due diligence." },
  { id: 21, question: "A Texas esthetician who changes their mailing address must notify TDLR within:", question_es: "Un esteticista de Texas que cambia su dirección postal debe notificar a TDLR dentro de:", options: ["30 days of the address change", "90 days of the address change", "The next license renewal period", "6 months — address updates are only required at renewal"], options_es: ["30 días del cambio de dirección", "90 días del cambio de dirección", "El próximo período de renovación de licencia", "6 meses — las actualizaciones de dirección solo se requieren en la renovación"], correct: 0, explanation: "TDLR requires all licensees to update their contact information (address, name) within 30 days of any change. Keeping contact information current ensures TDLR can reach the licensee regarding renewals, CE requirements, and compliance matters." },
  { id: 22, question: "When a Texas esthetician has a criminal conviction, TDLR:", question_es: "Cuando un esteticista de Texas tiene una condena criminal, TDLR:", options: ["Reviews the conviction on a case-by-case basis under Texas Occupations Code Chapter 53 to determine whether it is relevant to esthetics and potentially disqualifying", "Automatically denies the license regardless of the nature of the offense", "Only considers felony convictions — misdemeanors are irrelevant to licensure", "Takes no action unless the conviction was directly related to a cosmetology violation"], options_es: ["Revisa la condena caso por caso bajo el Capítulo 53 del Código de Ocupaciones de Texas para determinar si es relevante para la estética y potencialmente descalificante", "Niega automáticamente la licencia independientemente de la naturaleza del delito", "Solo considera condenas por delitos graves — los delitos menores son irrelevantes para la licencia", "No toma ninguna acción a menos que la condena esté directamente relacionada con una violación de cosmetología"], correct: 0, explanation: "Under Texas Occupations Code Chapter 53, TDLR evaluates criminal convictions case-by-case. Factors include: the nature and severity of the crime, its relationship to the practice of esthetics, and the time elapsed since conviction. Applicants may request a criminal history evaluation before applying." },
  { id: 23, question: "A Master Esthetician license in Texas requires:", question_es: "Una licencia de Esteticista Maestro en Texas requiere:", options: ["Completion of additional advanced training beyond the basic esthetics hours — Master Esthetician candidates must complete a more extensive curriculum that includes advanced skin care, lymphatic drainage, body treatments, and other advanced modalities", "Only 100 additional hours beyond the esthetician license", "A completely separate 2,000-hour program with no credit for the esthetician license hours", "A Master Esthetician license is not available in Texas — only the standard Esthetician license exists"], options_es: ["Completar capacitación avanzada adicional más allá de las horas básicas de estética — los candidatos a Esteticista Maestro deben completar un plan de estudios más extenso que incluye cuidado de la piel avanzado, drenaje linfático, tratamientos corporales y otras modalidades avanzadas", "Solo 100 horas adicionales más allá de la licencia de esteticista", "Un programa completamente separado de 2,000 horas sin crédito por las horas de licencia de esteticista", "Una licencia de Esteticista Maestro no está disponible en Texas — solo existe la licencia estándar de Esteticista"], correct: 0, explanation: "Texas does offer a Master Esthetician license under Chapter 1603. The Master Esthetician curriculum includes advanced esthetics modalities beyond the basic esthetician program. Master Estheticians may perform a broader range of advanced skin care services within their expanded scope." },
  { id: 24, question: "The primary purpose of Texas Occupations Code Chapter 1603 is:", question_es: "El propósito principal del Capítulo 1603 del Código de Ocupaciones de Texas es:", options: ["To protect the public health, safety, and welfare by establishing minimum standards for cosmetology education, licensing, and practice — including esthetics as a specialty", "To generate licensing fee revenue for the state of Texas", "To set pricing standards for cosmetology and esthetics services across the state", "To regulate the import of professional beauty products into Texas"], options_es: ["Proteger la salud pública, la seguridad y el bienestar estableciendo estándares mínimos para la educación, la licencia y la práctica de cosmetología — incluyendo la estética como especialidad", "Generar ingresos de tarifas de licencia para el estado de Texas", "Establecer estándares de precios para los servicios de cosmetología y estética en todo el estado", "Regular la importación de productos de belleza profesional en Texas"], correct: 0, explanation: "Like all professional licensing statutes, Chapter 1603's primary purpose is to protect the public by ensuring that practitioners meet minimum standards of education, competency, and safety before providing services that could affect client health. Revenue and price regulation are not statutory purposes." },
  { id: 25, question: "Texas Administrative Code Chapter 83 addresses esthetics sanitation requirements because:", question_es: "El Capítulo 83 del Código Administrativo de Texas aborda los requisitos de saneamiento de estética porque:", options: ["Esthetics services involve direct contact with skin, mucous membranes, and sometimes blood — improper sanitation creates significant risk of pathogen transmission between clients", "Sanitation rules are only for barbershops — esthetics establishments follow city health codes", "TDLR voluntarily adopted sanitation rules as a best practice, not as a legal requirement", "Chapter 83 sanitation rules only apply to nail services within an esthetics establishment"], options_es: ["Los servicios de estética implican contacto directo con la piel, las membranas mucosas y a veces la sangre — el saneamiento inadecuado crea un riesgo significativo de transmisión de patógenos entre clientes", "Las reglas de saneamiento son solo para barberías — los establecimientos de estética siguen los códigos de salud de la ciudad", "TDLR adoptó voluntariamente las reglas de saneamiento como una mejor práctica, no como un requisito legal", "Las reglas de saneamiento del Capítulo 83 solo aplican a los servicios de uñas dentro de un establecimiento de estética"], correct: 0, explanation: "Esthetics services — facials, extractions, waxing, chemical peels, and skin care — involve direct skin contact and can involve blood exposure (extractions, waxing). Proper sanitation is legally required under TAC Chapter 83 to protect clients from pathogen transmission and infections." },
  { id: 26, question: "A Texas esthetician whose license has expired must:", question_es: "Un esteticista de Texas cuya licencia ha vencido debe:", options: ["Stop performing esthetics services immediately and renew the license (with any applicable late fees and CE requirements) before resuming practice", "Continue practicing for up to 6 months under an automatic grace period with no penalty", "Simply begin working again — expired licenses are automatically reactivated upon payment of the renewal fee without any lapse consequences", "Re-enroll in a 750-hour esthetics program and take the full licensing exam again"], options_es: ["Dejar de realizar servicios de estética de inmediato y renovar la licencia (con cualquier tarifa por retraso aplicable y requisitos de EC) antes de reanudar la práctica", "Continuar practicando hasta 6 meses bajo un período de gracia automático sin penalidad", "Simplemente comenzar a trabajar de nuevo — las licencias vencidas se reactivan automáticamente al pagar la tarifa de renovación sin consecuencias de caducidad", "Volver a inscribirse en un programa de estética de 750 horas y tomar el examen de licencia completo nuevamente"], correct: 0, explanation: "An expired license means the esthetician is not authorized to practice. They must immediately stop performing services, complete any outstanding CE requirements, and renew the license (with any late fees that apply). Practicing on an expired license is the same as practicing without a license and is subject to administrative penalties." },
  { id: 27, question: "Texas allows license reciprocity for estheticians from other states when:", question_es: "Texas permite la reciprocidad de licencias para esteticistas de otros estados cuando:", options: ["The other state's licensing requirements are substantially equivalent to Texas standards — TDLR evaluates each state's requirements and may issue a Texas license by endorsement", "Any out-of-state license is automatically recognized — no evaluation is needed", "The applicant has worked in another state for at least 10 years regardless of that state's requirements", "Reciprocity is not available for esthetics in Texas — all applicants must complete Texas training"], options_es: ["Los requisitos de licencia del otro estado son sustancialmente equivalentes a los estándares de Texas — TDLR evalúa los requisitos de cada estado y puede emitir una licencia de Texas por respaldo", "Cualquier licencia de otro estado es reconocida automáticamente — no se necesita evaluación", "El solicitante ha trabajado en otro estado por al menos 10 años independientemente de los requisitos de ese estado", "La reciprocidad no está disponible para la estética en Texas — todos los solicitantes deben completar la capacitación de Texas"], correct: 0, explanation: "Texas may issue a license by endorsement (reciprocity) to estheticians licensed in other states if that state's requirements are substantially equivalent to Texas. TDLR evaluates the applicant's credentials against Texas standards before granting endorsement." },
  { id: 28, question: "An 'inactive' Texas esthetics license means:", question_es: "Una licencia de estética de Texas 'inactiva' significa:", options: ["The esthetician has voluntarily placed the license on inactive status — the license is maintained but the esthetician cannot provide services until they reactivate the license and meet any applicable requirements", "The license has expired due to non-renewal and is no longer valid", "The esthetician's license has been suspended by TDLR for violations", "The license is in active good standing with no restrictions"], options_es: ["El esteticista ha colocado voluntariamente la licencia en estado inactivo — la licencia se mantiene pero el esteticista no puede prestar servicios hasta que reactive la licencia y cumpla con los requisitos aplicables", "La licencia ha vencido debido a la falta de renovación y ya no es válida", "La licencia del esteticista ha sido suspendida por TDLR por violaciones", "La licencia está en buen estado activo sin restricciones"], correct: 0, explanation: "A voluntarily inactive license allows an esthetician to maintain their license while not actively practicing (e.g., during extended leave or career break). No services may be provided on an inactive license. To resume practice, the esthetician must reactivate by meeting all current requirements." },
  { id: 29, question: "Safety Data Sheets (SDS) must be maintained in a Texas esthetics establishment because:", question_es: "Las Hojas de Datos de Seguridad (SDS) deben mantenerse en un establecimiento de estética de Texas porque:", options: ["OSHA's Hazard Communication Standard requires that SDS be accessible to all employees for every hazardous chemical used in the workplace — esthetics establishments use numerous chemical products", "TDLR requires SDS only for establishments with 5 or more licensed estheticians", "SDS are only required for products that contain bleach or other extreme irritants", "SDS are optional in Texas esthetics establishments if the products have child-resistant packaging"], options_es: ["El Estándar de Comunicación de Peligros de OSHA requiere que las SDS sean accesibles a todos los empleados para cada producto químico peligroso utilizado en el lugar de trabajo — los establecimientos de estética usan numerosos productos químicos", "TDLR requiere SDS solo para establecimientos con 5 o más esteticistas con licencia", "Las SDS solo se requieren para productos que contienen lejía u otros irritantes extremos", "Las SDS son opcionales en los establecimientos de estética de Texas si los productos tienen envase a prueba de niños"], correct: 0, explanation: "OSHA's Hazard Communication Standard (29 CFR 1910.1200) requires SDS for all hazardous chemicals in the workplace. Esthetics establishments use many chemicals (chemical peels, waxing agents, toners, solvents) that require SDS documentation accessible to all employees for safety in case of exposure." },
  { id: 30, question: "The primary legal distinction between an employee esthetician and a booth renter in a Texas esthetics establishment is:", question_es: "La principal distinción legal entre un esteticista empleado y un arrendatario de espacio en un establecimiento de estética de Texas es:", options: ["Control: the owner controls employees' schedules, prices, and methods, while a booth renter is an independent business operator who pays rent to use the space and controls their own practice", "Booth renters are allowed to perform services that employees cannot", "Employee estheticians must hold a higher-level license than booth renters", "There is no legal distinction — both are treated identically under TDLR rules"], options_es: ["Control: el propietario controla los horarios, precios y métodos de los empleados, mientras que un arrendatario de espacio es un operador de negocio independiente que paga alquiler para usar el espacio y controla su propia práctica", "Los arrendatarios de espacio pueden realizar servicios que los empleados no pueden", "Los esteticistas empleados deben tener una licencia de nivel superior que los arrendatarios de espacio", "No hay distinción legal — ambos son tratados de manera idéntica bajo las reglas de TDLR"], correct: 0, explanation: "The legal distinction between employee and independent contractor (booth renter) turns on the degree of control. Employees are directed by their employer. Booth renters operate independently, set their own schedules and prices, and pay rent. Both must hold their own valid esthetician licenses." },
  { id: 31, question: "Under Texas law, a licensed esthetician may perform superficial chemical peels because:", question_es: "Según la ley de Texas, un esteticista con licencia puede realizar peels químicos superficiales porque:", options: ["Superficial chemical peels that exfoliate only the stratum corneum (outermost epidermal layer) fall within the esthetics scope of practice as defined in Texas Occupations Code Chapter 1603", "All chemical peel depths are within the esthetics scope in Texas without restriction", "Only cosmetology operators (not estheticians) are permitted to perform any chemical peels in Texas", "Chemical peels require a separate physician's supervision letter for each client"], options_es: ["Los peels químicos superficiales que exfolian solo el estrato córneo (la capa epidérmica más externa) caen dentro del alcance de práctica de estética según lo definido en el Capítulo 1603 del Código de Ocupaciones de Texas", "Todas las profundidades de peel químico están dentro del alcance de estética en Texas sin restricción", "Solo los operadores de cosmetología (no los esteticistas) tienen permitido realizar peels químicos en Texas", "Los peels químicos requieren una carta de supervisión médica separada para cada cliente"], correct: 0, explanation: "Texas estheticians may perform superficial chemical exfoliation that affects only the stratum corneum. Medium and deep peels that penetrate beyond the epidermis into the dermis are considered medical procedures and require a physician's license or physician supervision. Estheticians must stay within the superficial scope." },
  { id: 32, question: "Microdermabrasion is within the Texas esthetician scope of practice because:", question_es: "La microdermoabrasión está dentro del alcance de práctica del esteticista de Texas porque:", options: ["It is a mechanical (non-ablative) exfoliation procedure that removes dead cells from the stratum corneum surface — consistent with the esthetics scope of superficial exfoliation under Chapter 1603", "Microdermabrasion creates deep dermal wounds and is therefore a medical procedure requiring physician oversight", "Microdermabrasion is exclusively performed by cosmetology operators, not estheticians, in Texas", "Texas has not specifically addressed microdermabrasion — estheticians use professional judgment without regulatory guidance"], options_es: ["Es un procedimiento de exfoliación mecánica (no ablativa) que elimina las células muertas de la superficie del estrato córneo — consistente con el alcance de estética de exfoliación superficial bajo el Capítulo 1603", "La microdermoabrasión crea heridas dérmicas profundas y por lo tanto es un procedimiento médico que requiere supervisión médica", "La microdermoabrasión es realizada exclusivamente por operadores de cosmetología, no esteticistas, en Texas", "Texas no ha abordado específicamente la microdermoabrasión — los esteticistas usan el juicio profesional sin guía regulatoria"], correct: 0, explanation: "Microdermabrasion uses a mechanical device (crystals or diamond tip) to exfoliate the outermost layer of the epidermis (stratum corneum). Because it is superficial and non-ablative, it falls within the esthetics scope of mechanical exfoliation. Ablative laser treatments that penetrate deeper are outside scope." },
  { id: 33, question: "A Texas esthetician must refer a client to a physician when:", question_es: "Un esteticista de Texas debe referir a un cliente a un médico cuando:", options: ["The client presents a skin condition, lesion, rash, or symptom that appears to require medical diagnosis or treatment — such as suspected skin cancer, a suspicious mole, an infection, or a condition beyond the scope of esthetics", "The client's skin is simply dry or dehydrated", "A client requests a product the esthetician does not carry in the establishment", "The client has a known allergy to a fragrance ingredient"], options_es: ["El cliente presenta una condición cutánea, lesión, erupción o síntoma que parece requerir diagnóstico o tratamiento médico — como sospecha de cáncer de piel, un lunar sospechoso, una infección o una condición más allá del alcance de la estética", "La piel del cliente simplemente está seca o deshidratada", "Un cliente solicita un producto que el esteticista no tiene en el establecimiento", "El cliente tiene una alergia conocida a un ingrediente de fragancia"], correct: 0, explanation: "Estheticians are not licensed to diagnose or treat medical conditions. When a client presents with symptoms suggesting a medical condition (suspicious lesion, possible infection, undiagnosed rash, signs of a communicable disease), the esthetician must decline to service the affected area and refer the client to a physician." },
  { id: 34, question: "The PSI Texas Esthetician written examination covers which primary content areas?", question_es: "¿Cuáles son las principales áreas de contenido cubiertas en el examen escrito de Esteticista de Texas de PSI?", options: ["Licensing & Regulation, Infection Control, Nail Structure & Analysis, Nail Care, Skin Care, Facial Treatments, Hair Removal, and Facial Makeup", "Only skin care and facial treatments — other topics are covered in the practical exam", "Texas business law and tax regulations for esthetics establishments", "Anatomy and physiology at the same depth as a nursing license exam"], options_es: ["Licencias y Regulaciones, Control de Infecciones, Estructura y Análisis de Uñas, Cuidado de Uñas, Cuidado de la Piel, Tratamientos Faciales, Depilación y Maquillaje Facial", "Solo cuidado de la piel y tratamientos faciales — otros temas se cubren en el examen práctico", "Derecho comercial de Texas y regulaciones fiscales para establecimientos de estética", "Anatomía y fisiología al mismo nivel que un examen de licencia de enfermería"], correct: 0, explanation: "The PSI Texas Esthetician written exam covers eight content areas: Licensing & Regulation, Infection Control, Nail Structure & Analysis, Nail Care, Skin Care, Facial Treatments, Hair Removal, and Facial Makeup. All eight areas are tested on the written theory examination." },
  { id: 35, question: "TDLR administrative penalties for esthetics violations are:", question_es: "Las penalidades administrativas de TDLR para las violaciones de estética son:", options: ["Based on a penalty schedule that assigns fines according to the severity of the violation and whether it is a first or repeat offense — more serious or repeated violations carry higher penalties", "A flat $500 fine for every violation regardless of type or severity", "Only imposed on establishment owners, not individual estheticians", "Determined solely by the TDLR inspector's discretion without a standard schedule"], options_es: ["Basadas en un cronograma de penalidades que asigna multas según la gravedad de la violación y si es una primera o repetida infracción — las violaciones más graves o repetidas conllevan penalidades más altas", "Una multa fija de $500 por cada violación independientemente del tipo o gravedad", "Impuestas solo a los propietarios del establecimiento, no a los esteticistas individuales", "Determinadas únicamente por la discreción del inspector de TDLR sin un cronograma estándar"], correct: 0, explanation: "TDLR's penalty schedule considers: the type and severity of the violation, whether it creates a risk to public health, the number of prior violations, and mitigating factors. Penalties can be imposed on both the establishment and individual estheticians depending on the nature of the violation." },
  { id: 36, question: "Texas esthetics schools (cosmetology schools offering esthetics programs) must:", question_es: "Las escuelas de estética de Texas (escuelas de cosmetología que ofrecen programas de estética) deben:", options: ["Obtain a TDLR school license and meet curriculum and facility standards established in TAC Chapter 83 — only hours from TDLR-licensed schools count toward licensure", "Register with the Texas Education Agency (TEA) as private schools — TDLR does not license esthetics schools", "Be accredited by a national accreditation body without TDLR involvement", "Only require city-level business permits — no state license is needed for esthetics education"], options_es: ["Obtener una licencia escolar de TDLR y cumplir con los estándares de currículo e instalaciones establecidos en el Capítulo 83 de TAC — solo las horas de escuelas con licencia de TDLR cuentan para la licencia", "Registrarse con la Agencia de Educación de Texas (TEA) como escuelas privadas — TDLR no licencia escuelas de estética", "Estar acreditadas por un organismo nacional de acreditación sin participación de TDLR", "Solo requerir permisos comerciales a nivel de ciudad — no se necesita licencia estatal para la educación de estética"], correct: 0, explanation: "All esthetics schools in Texas must hold a TDLR school license. TDLR establishes the required curriculum hours (750 for esthetics), content areas, instructor qualifications, and facility standards. Only hours earned at TDLR-licensed schools are counted toward the licensing requirement." },
  { id: 37, question: "An esthetics establishment license in Texas is location-specific, meaning:", question_es: "Una licencia de establecimiento de estética en Texas es específica de la ubicación, lo que significa:", options: ["If the establishment moves to a new physical address or changes ownership, a new establishment license must be obtained for the new location or new owner — the existing license does not transfer", "The establishment license is portable and can be used at any location the owner operates in Texas", "The establishment license automatically transfers when the building is sold", "An establishment license covers all locations the owner operates statewide"], options_es: ["Si el establecimiento se muda a una nueva dirección física o cambia de propietario, se debe obtener una nueva licencia de establecimiento para la nueva ubicación o el nuevo propietario — la licencia existente no se transfiere", "La licencia del establecimiento es portátil y puede usarse en cualquier ubicación que el propietario opere en Texas", "La licencia del establecimiento se transfiere automáticamente cuando se vende el edificio", "Una licencia de establecimiento cubre todas las ubicaciones que el propietario opera en todo el estado"], correct: 0, explanation: "The establishment license is specific to both the owner and the physical location. A change of address (the establishment moves) or a change of ownership both require a new establishment license. Operating at a new location under the old license is a TDLR violation." },
  { id: 38, question: "Which act by a Texas esthetician constitutes 'unprofessional conduct' under TDLR rules?", question_es: "¿Qué acto de un esteticista de Texas constituye 'conducta no profesional' bajo las reglas de TDLR?", options: ["Practicing while impaired by alcohol or drugs, performing services in a manner that violates sanitation rules, engaging in fraud or misrepresentation, or failing to maintain appropriate professional boundaries with clients", "Charging prices that are lower than the market average for services", "Using generic professional products instead of premium brand-name products", "Offering clients a loyalty discount program"], options_es: ["Practicar mientras está bajo la influencia del alcohol o las drogas, realizar servicios de manera que viola las reglas de saneamiento, participar en fraude o tergiversación, o no mantener límites profesionales apropiados con los clientes", "Cobrar precios más bajos que el promedio del mercado por los servicios", "Usar productos profesionales genéricos en lugar de productos de marca premium", "Ofrecer a los clientes un programa de descuento por lealtad"], correct: 0, explanation: "Unprofessional conduct under Texas esthetics rules includes: practicing while impaired, violating sanitation standards, fraud in obtaining a license, sexual misconduct, false advertising, and conduct that demonstrates unfitness to practice. TDLR may suspend or revoke a license for unprofessional conduct." },
  { id: 39, question: "A Texas esthetician with a communicable condition affecting the skin of their hands must:", question_es: "Un esteticista de Texas con una condición contagiosa que afecta la piel de sus manos debe:", options: ["Refrain from performing any hands-on services until the condition has resolved or a physician has confirmed they are no longer contagious — wearing gloves alone may be insufficient depending on the condition", "Continue working and simply wear extra gloves to prevent transmission", "Notify all past clients within 30 days by certified mail", "Continue working but avoid services involving chemical products"], options_es: ["Abstenerse de realizar cualquier servicio práctico hasta que la condición se haya resuelto o un médico haya confirmado que ya no son contagiosos — solo usar guantes puede ser insuficiente dependiendo de la condición", "Seguir trabajando y simplemente usar guantes adicionales para prevenir la transmisión", "Notificar a todos los clientes anteriores dentro de los 30 días por correo certificado", "Seguir trabajando pero evitar los servicios que involucran productos químicos"], correct: 0, explanation: "Estheticians with communicable conditions must stop performing services to protect clients. Direct skin-to-skin contact during esthetics services creates transmission risk. A physician's clearance is advisable before returning. TDLR rules require estheticians to not perform services under conditions that endanger client health." },
  { id: 40, question: "TDLR-approved continuing education for Texas estheticians may cover:", question_es: "La educación continua aprobada por TDLR para esteticistas de Texas puede cubrir:", options: ["Infection control and sanitation, professional ethics, safety standards, advanced esthetics techniques, and other topics approved by TDLR that maintain or expand professional knowledge relevant to esthetics practice", "Only topics covered in the original 750-hour esthetics curriculum with no new subjects", "Exclusively business management and marketing skills", "National cosmetology association courses regardless of TDLR approval status"], options_es: ["Control de infecciones y saneamiento, ética profesional, estándares de seguridad, técnicas de estética avanzadas y otros temas aprobados por TDLR que mantienen o amplían el conocimiento profesional relevante para la práctica de estética", "Solo los temas cubiertos en el plan de estudios original de 750 horas de estética sin nuevos temas", "Exclusivamente habilidades de gestión empresarial y marketing", "Cursos nacionales de asociaciones de cosmetología independientemente del estado de aprobación de TDLR"], correct: 0, explanation: "TDLR approves CE courses and providers for Texas estheticians. Approved topics include infection control, professional ethics, safety, and relevant technical subjects. CE providers must be approved by TDLR — courses from unapproved providers do not count toward the renewal requirement." },
  { id: 41, question: "Before performing a chemical service (such as a chemical peel or waxing) on a new esthetics client, the esthetician should:", question_es: "Antes de realizar un servicio químico (como un peel químico o encerado) en un nuevo cliente de estética, el esteticista debe:", options: ["Conduct a thorough client consultation and health history intake, and for skin-sensitizing services, perform a patch test to assess for allergic reactions", "Simply proceed with the service — consultations are optional for experienced estheticians", "Only perform a consultation for clients over 65 years of age", "Ask the client verbally whether they have allergies — no written documentation is needed"], options_es: ["Realizar una consulta exhaustiva con el cliente e intake del historial de salud, y para los servicios que sensibilizan la piel, realizar una prueba de parche para evaluar las reacciones alérgicas", "Simplemente proceder con el servicio — las consultas son opcionales para los esteticistas experimentados", "Solo realizar una consulta para clientes mayores de 65 años", "Preguntar verbalmente al cliente si tiene alergias — no se necesita documentación escrita"], correct: 0, explanation: "A client consultation and health intake is essential before chemical services. It identifies contraindications (medications, skin conditions, allergies), guides product selection, and establishes informed consent. Patch testing before sensitizing products (chemical peels, tints, waxes) detects potential allergic reactions." },
  { id: 42, question: "Esthetics services performed at a Texas esthetics school's student clinic must:", question_es: "Los servicios de estética realizados en la clínica estudiantil de una escuela de estética de Texas deben:", options: ["Be performed by enrolled students under the supervision of a TDLR-licensed instructor — clients must be informed they are receiving services from students in training", "Be performed only by licensed estheticians even at a school clinic — students may observe only", "Be free of charge to all clients since student work is unpaid training", "Meet a lower sanitation standard than licensed establishments since students are still learning"], options_es: ["Ser realizados por estudiantes matriculados bajo la supervisión de un instructor con licencia de TDLR — los clientes deben ser informados de que están recibiendo servicios de estudiantes en entrenamiento", "Ser realizados solo por esteticistas con licencia incluso en una clínica escolar — los estudiantes solo pueden observar", "Ser gratuitos para todos los clientes ya que el trabajo estudiantil es capacitación no remunerada", "Cumplir con un estándar de saneamiento más bajo que los establecimientos con licencia ya que los estudiantes aún están aprendiendo"], correct: 0, explanation: "Student clinic services count toward the required education hours. They must be supervised by a licensed instructor, performed using proper sanitation, and clients must know they are receiving student services. Sanitation standards are the same as for licensed establishments — there is no lower standard for school clinics." },
  { id: 43, question: "Texas Occupations Code Chapter 53 is relevant to esthetics licensure because:", question_es: "El Capítulo 53 del Código de Ocupaciones de Texas es relevante para las licencias de estética porque:", options: ["It establishes the framework for how TDLR evaluates criminal history records when determining license eligibility — including the right to request a pre-determination of eligibility before investing in training", "It sets the specific curriculum hours for esthetics education programs", "It establishes pricing regulations for esthetics services statewide", "It authorizes TDLR to inspect establishments and issue violation notices"], options_es: ["Establece el marco sobre cómo TDLR evalúa los registros de historial criminal al determinar la elegibilidad de la licencia — incluyendo el derecho a solicitar una predeterminación de elegibilidad antes de invertir en la capacitación", "Establece las horas específicas del plan de estudios para los programas de educación en estética", "Establece regulaciones de precios para los servicios de estética en todo el estado", "Autoriza a TDLR para inspeccionar establecimientos y emitir avisos de violación"], correct: 0, explanation: "Texas Occupations Code Chapter 53 governs the use of criminal history in occupational licensing decisions. It gives applicants the right to request a criminal history evaluation from TDLR before enrolling in a training program, providing clarity on whether past convictions would bar licensure." },
  { id: 44, question: "The difference between a licensed esthetician and a licensed cosmetologist in Texas in terms of scope of practice is:", question_es: "La diferencia entre un esteticista con licencia y un cosmetólogo con licencia en Texas en términos de alcance de práctica es:", options: ["A cosmetologist is licensed for hair cutting/styling/coloring, nail care, and skin care; an esthetician's scope is focused on skin care, facial treatments, hair removal, and makeup but does NOT include cutting hair on the scalp", "There is no difference — both licenses authorize exactly the same services", "An esthetician has a broader scope than a cosmetologist in Texas", "A cosmetologist cannot perform facial treatments — those are reserved exclusively for estheticians"], options_es: ["Un cosmetólogo tiene licencia para cortar/peinar/colorear el cabello, cuidado de uñas y cuidado de la piel; el alcance del esteticista se enfoca en el cuidado de la piel, tratamientos faciales, depilación y maquillaje pero NO incluye cortar el cabello del cuero cabelludo", "No hay diferencia — ambas licencias autorizan exactamente los mismos servicios", "Un esteticista tiene un alcance más amplio que un cosmetólogo en Texas", "Un cosmetólogo no puede realizar tratamientos faciales — estos están reservados exclusivamente para esteticistas"], correct: 0, explanation: "A Texas Cosmetology Operator (cosmetologist) license covers hair services (cut, color, style), nail services, and skin care. The Esthetician license covers skin care, facials, hair removal, and makeup — but not hair cutting or chemical services on scalp hair. Both may hold dual licenses." },
  { id: 45, question: "A Texas esthetician may hold both an Esthetician license and a Cosmetology Operator license. In this situation:", question_es: "Un esteticista de Texas puede tener tanto una licencia de Esteticista como una licencia de Operador de Cosmetología. En esta situación:", options: ["The dual licensee may perform all services authorized under both licenses, but must comply with the rules applicable to each license for the specific services performed", "The cosmetologist license supersedes the esthetics license — only cosmetology rules apply", "The esthetics license is automatically voided when a cosmetology license is issued", "The dual licensee must work in two separate locations — one for esthetics services, one for cosmetology services"], options_es: ["El titular de doble licencia puede realizar todos los servicios autorizados bajo ambas licencias, pero debe cumplir con las reglas aplicables a cada licencia para los servicios específicos realizados", "La licencia de cosmetólogo supera a la licencia de estética — solo se aplican las reglas de cosmetología", "La licencia de estética se anula automáticamente cuando se emite una licencia de cosmetología", "El titular de doble licencia debe trabajar en dos ubicaciones separadas — una para servicios de estética, otra para servicios de cosmetología"], correct: 0, explanation: "Holding dual licenses expands the practitioner's authorized scope to include all services under both licenses. Both licenses must remain current. Each service must be performed in compliance with the rules for that license type." },
  { id: 46, question: "A Texas esthetics establishment must retain client service records for:", question_es: "Un establecimiento de estética de Texas debe retener los registros de servicio del cliente por:", options: ["A minimum period as required by TDLR and applicable Texas law — records should be maintained to protect the establishment and the client in case of adverse reactions or disputes", "Only 30 days after the service is performed", "Indefinitely — records can never be destroyed under Texas law", "There is no requirement to keep client records in esthetics — verbal documentation is sufficient"], options_es: ["Un período mínimo requerido por TDLR y la ley de Texas aplicable — los registros deben mantenerse para proteger al establecimiento y al cliente en caso de reacciones adversas o disputas", "Solo 30 días después de que se realiza el servicio", "Indefinidamente — los registros nunca pueden destruirse según la ley de Texas", "No existe requisito de mantener registros de clientes en estética — la documentación verbal es suficiente"], correct: 0, explanation: "Client records (intake forms, service records, patch test results, product reactions) should be retained for the period specified by TDLR rules and Texas retention requirements. Records serve as legal protection for both the client and the esthetician in the event of adverse reactions, disputes, or TDLR audits." },
  { id: 47, question: "The owner or operator of a Texas esthetics establishment is legally responsible for:", question_es: "El propietario u operador de un establecimiento de estética de Texas es legalmente responsable de:", options: ["Ensuring the entire establishment complies with all applicable TDLR rules — including sanitation, licensing display, and safety — even for violations committed by individual estheticians working at the location", "Only their own individual practice and client interactions", "Violations committed by booth renters — who are independent contractors — at the owner's establishment", "Filing quarterly compliance reports with TDLR on behalf of all licensees at the location"], options_es: ["Garantizar que todo el establecimiento cumpla con todas las reglas de TDLR aplicables — incluyendo saneamiento, exhibición de licencias y seguridad — incluso para violaciones cometidas por esteticistas individuales que trabajan en la ubicación", "Solo su propia práctica individual e interacciones con clientes", "Violaciones cometidas por arrendatarios de espacio — que son contratistas independientes — en el establecimiento del propietario", "Presentar informes trimestrales de cumplimiento ante TDLR en nombre de todos los titulares de licencia en la ubicación"], correct: 0, explanation: "Establishment owners/operators have an affirmative duty to ensure their establishment operates in full compliance with TDLR rules. Both the establishment license and individual esthetician licenses can be subject to enforcement for violations found during inspections. Owners may also be liable for booth renters' sanitation compliance at their facility." },
  { id: 48, question: "The provision of Texas Occupations Code that authorizes TDLR to impose administrative fines on estheticians for violations is:", question_es: "La disposición del Código de Ocupaciones de Texas que autoriza a TDLR a imponer multas administrativas a los esteticistas por violaciones es:", options: ["Found within Chapter 1603 and TDLR's general enforcement authority under applicable statutes — TDLR may impose administrative penalties for violating licensing, sanitation, or professional conduct requirements", "Found only in the Texas Penal Code — esthetics violations are criminal matters, not civil", "Not established by statute — TDLR relies on voluntary compliance without enforcement authority", "Found exclusively in the Texas Administrative Code Chapter 83 with no statutory basis in the Occupations Code"], options_es: ["Encontrada dentro del Capítulo 1603 y la autoridad de aplicación general de TDLR bajo los estatutos aplicables — TDLR puede imponer penalidades administrativas por violar los requisitos de licencia, saneamiento o conducta profesional", "Encontrada solo en el Código Penal de Texas — las violaciones de estética son asuntos penales, no civiles", "No establecida por estatuto — TDLR depende del cumplimiento voluntario sin autoridad de aplicación", "Encontrada exclusivamente en el Capítulo 83 del Código Administrativo de Texas sin base estatutaria en el Código de Ocupaciones"], correct: 0, explanation: "TDLR's administrative enforcement authority derives from Texas Occupations Code Chapter 1603 and TDLR's general enabling statutes. Administrative penalties (fines) are civil, not criminal, and are assessed through an administrative process that includes due process protections and the right to appeal." },
  { id: 49, question: "Before a new Texas esthetics establishment can open for business, it must:", question_es: "Antes de que un nuevo establecimiento de estética de Texas pueda abrir para el negocio, debe:", options: ["Obtain a TDLR establishment license, pass a pre-opening inspection to verify sanitation and facility standards are met, and ensure all practicing estheticians hold valid individual licenses", "Only obtain a city business license — TDLR establishment licensing is optional for new establishments", "Pass only a fire safety inspection — TDLR sanitation inspections occur after opening", "Have at least 3 licensed estheticians on staff before the establishment license is issued"], options_es: ["Obtener una licencia de establecimiento de TDLR, pasar una inspección previa a la apertura para verificar que se cumplan los estándares de saneamiento e instalaciones, y asegurarse de que todos los esteticistas que practican tengan licencias individuales válidas", "Solo obtener una licencia comercial de la ciudad — las licencias de establecimiento de TDLR son opcionales para nuevos establecimientos", "Solo pasar una inspección de seguridad contra incendios — las inspecciones de saneamiento de TDLR ocurren después de la apertura", "Tener al menos 3 esteticistas con licencia en el personal antes de que se emita la licencia del establecimiento"], correct: 0, explanation: "New esthetics establishments must obtain a TDLR establishment license before opening. TDLR may conduct a pre-opening inspection to ensure the facility meets all sanitation, equipment, and safety requirements. All estheticians who will practice there must hold current individual licenses." },
  { id: 50, question: "A Texas esthetics license application must include:", question_es: "Una solicitud de licencia de estética de Texas debe incluir:", options: ["Proof of completing the required education hours at a TDLR-licensed school, proof of passing both the PSI written and practical exams, applicable fees, and any other documentation required by TDLR", "Only proof of age and payment of the application fee", "A letter of recommendation from the esthetics school's director", "A notarized statement from a licensed physician confirming the applicant's skin health"], options_es: ["Comprobante de haber completado las horas de educación requeridas en una escuela con licencia de TDLR, comprobante de aprobar tanto los exámenes escritos como los prácticos de PSI, tarifas aplicables y cualquier otra documentación requerida por TDLR", "Solo comprobante de edad y pago de la tarifa de solicitud", "Una carta de recomendación del director de la escuela de estética", "Una declaración notariada de un médico con licencia que confirme la salud cutánea del solicitante"], correct: 0, explanation: "A complete Texas esthetics license application requires: proof of education (school transcript/certificate verifying 750 hours from a TDLR-licensed school), passing scores on both PSI exams, the application fee, and any other required documentation such as criminal history disclosure." },
]

